 SET search_path TO ''
AS $function$
begin
 if TG_TABLE_NAME='app_settings' then
  if TG_OP='DELETE' then if OLD.key='commercial_data_revision' then return null;end if;
  elsif NEW.key='commercial_data_revision' then return null;end if;
 end if;
 insert into public.app_settings(key,value) values('commercial_data_revision',clock_timestamp()::text) on conflict(key) do update set value=excluded.value;return null;
end $function$

CREATE OR REPLACE FUNCTION public.trg_item_enrich()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_pm record;
  v_cb record;
begin
  select category, brand, warna, name into v_pm from product_master where item_name = new.item_name;
  select brand into v_cb from category_brand where category = new.category_name;
  new.category := coalesce(v_pm.category, new.category_name);
  new.brand    := coalesce(v_pm.brand, v_cb.brand, 'LAINNYA');
  new.product  := coalesce(v_pm.name, regexp_replace(new.item_name, '\s+(PDK|PJG)\s+\S+$', ''));
  new.warna    := coalesce(nullif(v_pm.warna,''), nullif(trim(substring(new.item_name, '^(.*?)\s+(\d{2}S|\+\s*RIB|WK\s+MYNO)(\s|$)')), ''));
  new.size     := nullif(substring(upper(trim(new.item_name)), '\s(XS|S|M|L|XL|[2-9]XL|XXL|XXXL|\d{1,2}|ALL|FS)$'), '');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_refresh_item_enrich_from_catbrand()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  perform public.recompute_item_enrich(
    (select array_agg(id) from item_sales where category_name = coalesce(new.category, old.category))
  );
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_refresh_item_enrich_from_master()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  perform public.recompute_item_enrich(
    (select array_agg(id) from item_sales where item_name = coalesce(new.item_name, old.item_name))
  );
  return null;
end;
$function$
